# Chèn an toàn: nạp - append - ghi; bỏ qua slug đã có.
d = json.load(open(F, encoding="utf-8")) if os.path.exists(F) else []
have = {p["slug"] for p in d}
added = [p for p in NEW if p["slug"] not in have]
d += added
json.dump(d, open(F, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
print("Tong so ban ghi hien co:", len(d))
print("Da them moi:", len(added), "/", len(NEW), "(bo qua trung slug:", len(NEW) - len(added), ")")
for p in added:
    print("  +", p["slug"], "|", p["name_vi"])

